    seen = [[False] * w for _ in range(h)]
    dirs4 = ((1, 0), (-1, 0), (0, 1), (0, -1))
    dirs8 = tuple((dr, dc) for dr in (-1, 0, 1) for dc in (-1, 0, 1) if dr or dc)

    # A bounded 4-connected zero region is an interior. Color only its
    # one-cell rim adjacent to the enclosing 1s.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            region = []
            touches_edge = False
            bordering_ones = set()
            while q:
                y, x = q.popleft()
                region.append((y, x))
                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    touches_edge = True
                for dy, dx in dirs4:
                    yy, xx = y + dy, x + dx
                    if not (0 <= yy < h and 0 <= xx < w):
                        continue
                    if grid[yy][xx] == 0 and not seen[yy][xx]:
                        seen[yy][xx] = True
                        q.append((yy, xx))
                    elif grid[yy][xx] == 1:
                        bordering_ones.add((yy, xx))
            if touches_edge or not bordering_ones:
                continue

            region_set = set(region)
            for y, x in region:
                if any((y + dy, x + dx) in bordering_ones for dy, dx in dirs4):
                    out[y][x] = 3

            # Add color 2 to exterior cells in the 8-neighbor halo of the
            # boundary component(s) enclosing this region.
            boundary_seen = set()
            for sy, sx in bordering_ones:
                if (sy, sx) in boundary_seen:
                    continue
                component = []
                qq = deque([(sy, sx)])
                boundary_seen.add((sy, sx))
                while qq:
                    y, x = qq.popleft()
                    component.append((y, x))
                    for dy, dx in dirs4:
                        yy, xx = y + dy, x + dx
                        if (0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 1
                                and (yy, xx) not in boundary_seen):
                            boundary_seen.add((yy, xx))
                            qq.append((yy, xx))
                for y, x in component:
                    for dy, dx in dirs8:
                        yy, xx = y + dy, x + dx
                        if (0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0
                                and (yy, xx) not in region_set and seen[yy][xx]):
                            # Exterior means its zero component reaches an edge.
                            # This is checked below with a small flood-fill label.
                            pass

    # Label all zero regions again, then paint the exterior halo around any
    # 1 component adjacent to an enclosed region.
    seen = [[False] * w for _ in range(h)]
    exterior = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            region = []
            touches_edge = False
            while q:
                y, x = q.popleft()
                region.append((y, x))
                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    touches_edge = True
                for dy, dx in dirs4:
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0
                            and not seen[yy][xx]):
                        seen[yy][xx] = True
                        q.append((yy, xx))
            if touches_edge:
                for y, x in region:
                    exterior[y][x] = True

    # For each enclosed region, find all 1s in its 4-neighbor boundary and
    # paint adjacent exterior zeros in their 8-neighbor halo.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            # An interior-rim 3 marks adjacency to an enclosed zero region.
            # Collect these boundary 1s directly from neighboring 3 cells.
            if out[r][c] == 3:
                for dy, dx in dirs4:
                    y, x = r + dy, c + dx
                    if 0 <= y < h and 0 <= x < w and grid[y][x] == 1:
                        for ddy, ddx in dirs8:
                            yy, xx = y + ddy, x + ddx
                            if (0 <= yy < h and 0 <= xx < w and exterior[yy][xx]
                                    and grid[yy][xx] == 0 and out[yy][xx] == 0):
                                out[yy][xx] = 2
    return out
